    19→const (
    20→	version = "0.1.0-alpha"
    21→	banner  = `
    22→╔═══════════════════════════════════╗
    23→║   JuliaCC - Julia Compiler        ║
    24→║   Version: %s                     ║
    25→║   Go-based Implementation         ║
    26→╚═══════════════════════════════════╝
    27→`
    28→)
