    30→func main() {
    31→	// 플래그 정의
    32→	versionFlag := flag.Bool("version", false, "버전 출력")
    33→	helpFlag := flag.Bool("help", false, "도움말 출력")
    34→	outputFile := flag.String("o", "", "출력 파일명")
    35→	debugFlag := flag.Bool("debug", false, "디버그 모드")
    36→
    37→	flag.Parse()
    38→
    39→	// 플래그 처리
    40→	if *versionFlag {
    41→		fmt.Printf(banner, version)
    42→		os.Exit(0)
    43→	}
    44→
    45→	if *helpFlag {
    46→		printHelp()
    47→		os.Exit(0)
    48→	}
    49→
    50→	// 입력 파일 확인
    51→	args := flag.Args()
    52→	if len(args) == 0 {
    53→		fmt.Fprintf(os.Stderr, "오류: 입력 파일을 지정해주세요\n")
    54→		printHelp()
    55→		os.Exit(1)
    56→	}
    57→
    58→	inputFile := args[0]
    59→	if _, err := os.Stat(inputFile); err != nil {
    60→		fmt.Fprintf(os.Stderr, "오류: 파일을 열 수 없습니다: %s\n", inputFile)
    61→		os.Exit(1)
    62→	}
    63→
    64→	// 출력 파일명 기본값 설정
    65→	if *outputFile == "" {
    66→		ext := filepath.Ext(inputFile)
    67→		*outputFile = inputFile[:len(inputFile)-len(ext)] + ".out"
    68→	}
    69→
    70→	// 파일 읽기
    71→	source, err := ioutil.ReadFile(inputFile)
    72→	if err != nil {
    73→		fmt.Fprintf(os.Stderr, "오류: 파일을 읽을 수 없습니다: %v\n", err)
    74→		os.Exit(1)
    75→	}
    76→
    77→	// 컴파일 파이프라인
    78→	if err := compile(string(source), *debugFlag); err != nil {
    79→		fmt.Fprintf(os.Stderr, "컴파일 오류: %v\n", err)
    80→		os.Exit(1)
    81→	}
    82→
    83→	fmt.Printf("✅ 컴파일 성공: %s\n", *outputFile)
    84→}
