    86→func compile(source string, debug bool) error {
    87→	if debug {
    88→		fmt.Println("🐛 디버그 모드 활성화")
    89→	}
    90→
    91→	// Phase 1: Lexing
    92→	if debug {
    93→		fmt.Println("Phase 1: Lexing...")
    94→	}
    95→	lex := lexer.New(source)
    96→	tokens, err := lex.Tokenize()
    97→	if err != nil {
    98→		return fmt.Errorf("lexing error: %v", err)
    99→	}
   100→	if debug {
   101→		fmt.Printf("  ✓ %d tokens\n", len(tokens))
   102→	}
   103→
   104→	// Phase 2: Parsing
   105→	if debug {
   106→		fmt.Println("Phase 2: Parsing...")
   107→	}
   108→	p := parser.New(tokens)
   109→	program, err := p.Parse()
   110→	if err != nil {
   111→		return fmt.Errorf("parsing error: %v", err)
   112→	}
   113→	if debug {
   114→		fmt.Printf("  ✓ Parsed %d statements\n", len(program.Statements))
   115→	}
   116→
   117→	// Phase 3: Semantic Analysis
   118→	if debug {
   119→		fmt.Println("Phase 3: Semantic Analysis...")
   120→	}
   121→	analyzer := sema.NewAnalyzer()
   122→	_, err = analyzer.Analyze(program)
   123→	if err != nil {
   124→		return fmt.Errorf("semantic analysis error: %v", err)
   125→	}
   126→	if debug {
   127→		fmt.Println("  ✓ Semantic analysis passed")
   128→	}
   129→
   130→	// Phase 5: IR Generation
   131→	if debug {
   132→		fmt.Println("Phase 5: IR Generation...")
   133→	}
   134→	builder := ir.NewBuilder()
   135→	irModule, err := builder.Build(program)
   136→	if err != nil {
   137→		return fmt.Errorf("IR generation error: %v", err)
   138→	}
   139→	if debug {
   140→		fmt.Printf("  ✓ Generated IR module with %d functions\n", len(irModule.Functions))
   141→	}
   142→
   143→	// Phase 6: Type Inference
   144→	if debug {
   145→		fmt.Println("Phase 6: Type Inference...")
   146→	}
   147→	inferrer := typeinf.NewInferrer(irModule)
   148→	if err := inferrer.Infer(); err != nil {
   149→		return fmt.Errorf("type inference error: %v", err)
   150→	}
   151→	if debug {
   152→		fmt.Println("  ✓ Type inference complete")
   153→	}
   154→
   155→	// Phase 7: Optimization
   156→	if debug {
   157→		fmt.Println("Phase 7: Optimization...")
   158→	}
   159→	opt := optimizer.NewOptimizer(irModule)
   160→	if err := opt.Optimize(); err != nil {
   161→		return fmt.Errorf("optimization error: %v", err)
   162→	}
   163→	if debug {
   164→		fmt.Println("  ✓ Optimization complete")
   165→	}
   166→
   167→	// Phase 8: Codegen
   168→	if debug {
   169→		fmt.Println("Phase 8: Code Generation...")
   170→	}
   171→	cg := codegen.NewCodegen(irModule)
   172→	bytecode, err := cg.Generate()
   173→	if err != nil {
   174→		return fmt.Errorf("code generation error: %v", err)
   175→	}
   176→	if debug {
   177→		fmt.Printf("  ✓ Generated %d bytes of bytecode\n", len(bytecode.Code))
   178→	}
   179→
   180→	// Phase 8b: VM Execution
   181→	if debug {
   182→		fmt.Println("Phase 8b: Execution...")
   183→	}
   184→	vm := codegen.NewVM(bytecode)
   185→	result, err := vm.Run()
   186→	if err != nil {
   187→		return fmt.Errorf("execution error: %v", err)
   188→	}
   189→	if debug {
   190→		fmt.Printf("  ✓ Execution complete (result: %v)\n", result)
   191→	}
   192→
   193→	return nil
   194→}
