     3→// Phase 2: Parser - Julia 파서 구현
     4→
     5→import (
     6→	"fmt"
     7→	"juliacc/internal/ast"
     8→	"juliacc/internal/lexer"
     9→)
    10→
    11→// Parser - Julia 파서
    12→type Parser struct {
    13→	tokens    []lexer.Token
    14→	pos       int             // 현재 토큰 위치
    15→	current   lexer.Token     // 현재 토큰
    16→	errors    []ParserError
    17→	precMap   map[lexer.TokenType]int // 연산자 우선순위
    18→}
    19→
    20→// ParserError - 파서 에러
    21→type ParserError struct {
    22→	Message string
    23→	Token   lexer.Token
    24→}
    25→
    26→// NewParser - 새로운 파서 생성
    27→func NewParser(tokens []lexer.Token) *Parser {
    28→	p := &Parser{
    29→		tokens:  tokens,
    30→		pos:     0,
    31→		errors:  []ParserError{},
    32→		precMap: buildPrecedenceMap(),
    33→	}
    34→	p.advance()
    35→	return p
    36→}
    37→
    38→// advance - 다음 토큰으로 이동
    39→func (p *Parser) advance() {
    40→	if p.pos < len(p.tokens) {
    41→		p.current = p.tokens[p.pos]
    42→		p.pos++
    43→	}
    44→}
    45→
    46→// peek - n번째 앞의 토큰 보기
    47→func (p *Parser) peek(n int) lexer.Token {
    48→	pos := p.pos - 1 + n
    49→	if pos >= len(p.tokens) {
    50→		return p.tokens[len(p.tokens)-1] // EOF
    51→	}
    52→	return p.tokens[pos]
    53→}
    54→
    55→// match - 현재 토큰이 주어진 타입과 일치하는지 확인 및 소비
    56→func (p *Parser) match(types ...lexer.TokenType) bool {
    57→	for _, t := range types {
    58→		if p.current.Type == t {
    59→			p.advance()
    60→			return true
    61→		}
    62→	}
    63→	return false
    64→}
    65→
    66→// expect - 특정 토큰을 기대하고 소비, 실패 시 에러
    67→func (p *Parser) expect(tokenType lexer.TokenType) lexer.Token {
    68→	if p.current.Type != tokenType {
    69→		p.error(fmt.Sprintf("예상 %v, 얻은 %v", tokenType, p.current.Type))
    70→		return p.current
    71→	}
    72→	token := p.current
    73→	p.advance()
    74→	return token
    75→}
    76→
    77→// error - 에러 추가
    78→func (p *Parser) error(msg string) {
    79→	p.errors = append(p.errors, ParserError{
    80→		Message: msg,
    81→		Token:   p.current,
    82→	})
    83→}
    84→
    85→// Parse - 프로그램 파싱
    86→func (p *Parser) Parse() (*ast.Program, error) {
    87→	stmts := []ast.Stmt{}
    88→
    89→	for p.current.Type != lexer.TokenEOF {
    90→		// 개행 건너뛰기
    91→		if p.match(lexer.TokenNewline) {
    92→			continue
    93→		}
    94→
    95→		stmt := p.parseStatement()
    96→		if stmt != nil {
    97→			stmts = append(stmts, stmt)
    98→		}
    99→
   100→		// 개행 또는 세미콜론 건너뛰기
   101→		for p.match(lexer.TokenNewline, lexer.TokenSemicolon) {
   102→		}
   103→	}
   104→
   105→	if len(p.errors) > 0 {
   106→		return nil, fmt.Errorf("파싱 에러: %v", p.errors)
   107→	}
   108→
   109→	return &ast.Program{Statements: stmts}, nil
   110→}
   111→
   112→// parseStatement - 문 파싱
   113→func (p *Parser) parseStatement() ast.Stmt {
   114→	switch p.current.Type {
   115→	case lexer.TokenKeywordFunction:
   116→		return p.parseFunctionDecl()
   117→	case lexer.TokenKeywordStruct, lexer.TokenKeywordMutable:
   118→		return p.parseStructDecl()
   119→	case lexer.TokenKeywordIf:
   120→		return p.parseIfStmt()
   121→	case lexer.TokenKeywordWhile:
   122→		return p.parseWhileStmt()
   123→	case lexer.TokenKeywordFor:
   124→		return p.parseForStmt()
   125→	case lexer.TokenKeywordReturn:
   126→		return p.parseReturnStmt()
   127→	case lexer.TokenKeywordBreak:
   128→		p.advance()
   129→		return &ast.BreakStmt{Break: p.tokens[p.pos-2]}
   130→	case lexer.TokenKeywordContinue:
   131→		p.advance()
   132→		return &ast.ContinueStmt{Continue: p.tokens[p.pos-2]}
   133→	case lexer.TokenKeywordTry:
   134→		return p.parseTryStmt()
   135→	case lexer.TokenKeywordConst:
   136→		return p.parseConstDecl()
   137→	case lexer.TokenKeywordLet:
   138→		return p.parseLetStmt()
   139→	default:
   140→		return p.parseExprStmt()
   141→	}
   142→}
   143→
   144→// parseExprStmt - 표현식 문 파싱
   145→func (p *Parser) parseExprStmt() ast.Stmt {
   146→	expr := p.parseExpression()
   147→	if expr == nil {
   148→		return nil
   149→	}
   150→
   151→	// 할당인지 확인
   152→	if p.isAssignmentOp(p.current.Type) {
   153→		op := p.current.Type
   154→		opToken := p.current
   155→		p.advance()
   156→		right := p.parseExpression()
   157→		if right == nil {
   158→			p.error("할당의 우변이 필요합니다")
   159→			return nil
   160→		}
   161→		return &ast.Assignment{
   162→			Left:   expr,
   163→			Right:  right,
   164→			Op:     op,
   165→			Equal:  opToken,
   166→		}
   167→	}
   168→
   169→	return &ast.ExprStmt{Expr: expr}
   170→}
   171→
   172→// parseExpression - 표현식 파싱 (우선순위 클라이밍)
   173→func (p *Parser) parseExpression() ast.Expr {
   174→	return p.parseBinaryOp(0)
   175→}
   176→
   177→// parseBinaryOp - 이항 연산 파싱 (우선순위 클라이밍)
   178→func (p *Parser) parseBinaryOp(minPrec int) ast.Expr {
   179→	left := p.parseUnary()
   180→	if left == nil {
   181→		return nil
   182→	}
   183→
   184→	for p.isBinaryOp(p.current.Type) {
   185→		prec := p.getPrecedence(p.current.Type)
   186→		if prec < minPrec {
   187→			break
   188→		}
   189→
   190→		op := p.current.Type
   191→		opToken := p.current
   192→		p.advance()
   193→
   194→		// 우결합이면 prec, 좌결합이면 prec+1
   195→		nextPrec := prec
   196→		if p.isLeftAssociative(op) {
   197→			nextPrec = prec + 1
   198→		}
   199→
   200→		right := p.parseBinaryOp(nextPrec)
   201→		if right == nil {
   202→			p.error("이항 연산자의 우변이 필요합니다")
   203→			return nil
   204→		}
   205→
   206→		left = &ast.BinaryOp{
   207→			Left:    left,
   208→			Op:      op,
   209→			Right:   right,
   210→			OpToken: opToken,
   211→		}
   212→	}
   213→
   214→	return left
   215→}
   216→
   217→// parseUnary - 단항 연산 파싱
   218→func (p *Parser) parseUnary() ast.Expr {
   219→	if p.isUnaryOp(p.current.Type) {
   220→		op := p.current.Type
   221→		opToken := p.current
   222→		p.advance()
   223→		operand := p.parseUnary()
   224→		if operand == nil {
   225→			p.error("단항 연산자의 피연산자가 필요합니다")
   226→			return nil
   227→		}
   228→		return &ast.UnaryOp{
   229→			Op:      op,
   230→			Operand: operand,
   231→			OpToken: opToken,
   232→		}
   233→	}
   234→
   235→	return p.parsePostfix()
   236→}
   237→
   238→// parsePostfix - 후위 연산 파싱 (함수 호출, 인덱싱, 멤버 접근)
   239→func (p *Parser) parsePostfix() ast.Expr {
   240→	expr := p.parsePrimary()
   241→	if expr == nil {
   242→		return nil
   243→	}
   244→
   245→	for {
   246→		switch p.current.Type {
   247→		case lexer.TokenLparen:
   248→			// 함수 호출
   249→			lparen := p.current
   250→			p.advance()
   251→			args := p.parseArguments()
   252→			rparen := p.expect(lexer.TokenRparen)
   253→			expr = &ast.Call{
   254→				Function:  expr,
   255→				Arguments: args,
   256→				LParen:    lparen,
   257→				RParen:    rparen,
   258→			}
   259→
   260→		case lexer.TokenLbracket:
   261→			// 인덱싱
   262→			lbracket := p.current
   263→			p.advance()
   264→			indices := []ast.Expr{}
   265→			for p.current.Type != lexer.TokenRbracket {
   266→				idx := p.parseExpression()
   267→				if idx == nil {
   268→					p.error("인덱스 표현식이 필요합니다")
   269→					return nil
   270→				}
   271→				indices = append(indices, idx)
   272→				if !p.match(lexer.TokenComma) {
   273→					break
   274→				}
   275→			}
   276→			rbracket := p.expect(lexer.TokenRbracket)
   277→			expr = &ast.Index{
   278→				Object:   expr,
   279→				Index:    indices,
   280→				LBracket: lbracket,
   281→				RBracket: rbracket,
   282→			}
   283→
   284→		case lexer.TokenDot:
   285→			// 멤버 접근
   286→			dot := p.current
   287→			p.advance()
   288→			if p.current.Type != lexer.TokenIdentifier {
   289→				p.error("멤버 이름이 필요합니다")
   290→				return nil
   291→			}
   292→			field := p.current.Lexeme
   293→			p.advance()
   294→			expr = &ast.MemberAccess{
   295→				Object: expr,
   296→				Field:  field,
   297→				Dot:    dot,
   298→			}
   299→
   300→		case lexer.TokenDoubleColon:
   301→			// 타입 주석
   302→			colonColon := p.current
   303→			p.advance()
   304→			if p.current.Type != lexer.TokenIdentifier {
   305→				p.error("타입 이름이 필요합니다")
   306→				return nil
   307→			}
   308→			typeStr := p.current.Lexeme
   309→			p.advance()
   310→			expr = &ast.TypeAnnotation{
   311→				Expr:       expr,
   312→				Type:       typeStr,
   313→				ColonColon: colonColon,
   314→			}
   315→
   316→		default:
   317→			return expr
   318→		}
   319→	}
   320→}
   321→
   322→// parsePrimary - 기본 표현식 파싱
   323→func (p *Parser) parsePrimary() ast.Expr {
   324→	switch p.current.Type {
   325→	case lexer.TokenInteger, lexer.TokenFloat, lexer.TokenString,
   326→		lexer.TokenSymbol, lexer.TokenComplexNumber, lexer.TokenRationalNumber:
   327→		// 리터럴
   328→		token := p.current
   329→		p.advance()
   330→		return &ast.Literal{
   331→			Token: token,
   332→			Value: token.Lexeme,
   333→		}
   334→
   335→	case lexer.TokenKeywordTrue:
   336→		token := p.current
   337→		p.advance()
   338→		return &ast.Literal{Token: token, Value: true}
   339→
   340→	case lexer.TokenKeywordFalse:
   341→		token := p.current
   342→		p.advance()
   343→		return &ast.Literal{Token: token, Value: false}
   344→
   345→	case lexer.TokenKeywordNothing:
   346→		token := p.current
   347→		p.advance()
   348→		return &ast.Literal{Token: token, Value: nil}
   349→
   350→	case lexer.TokenIdentifier:
   351→		// 식별자
   352→		token := p.current
   353→		p.advance()
   354→		return &ast.Identifier{
   355→			Token: token,
   356→			Name:  token.Lexeme,
   357→		}
   358→
   359→	case lexer.TokenLparen:
   360→		// 괄호 표현식 또는 튜플
   361→		lparen := p.current
   362→		p.advance()
   363→		if p.match(lexer.TokenRparen) {
   364→			// 빈 튜플
   365→			return &ast.TupleLiteral{
   366→				Elements: []ast.Expr{},
   367→				LParen:   lparen,
   368→				RParen:   p.tokens[p.pos-1],
   369→			}
   370→		}
   371→		expr := p.parseExpression()
   372→		if expr == nil {
   373→			p.error("괄호 안에 표현식이 필요합니다")
   374→			return nil
   375→		}
   376→
   377→		// 튜플인지 확인 (쉼표가 있으면 튜플)
   378→		if p.match(lexer.TokenComma) {
   379→			elements := []ast.Expr{expr}
   380→			for p.current.Type != lexer.TokenRparen {
   381→				e := p.parseExpression()
   382→				if e == nil {
   383→					p.error("튜플 요소가 필요합니다")
   384→					return nil
   385→				}
   386→				elements = append(elements, e)
   387→				if !p.match(lexer.TokenComma) {
   388→					break
   389→				}
   390→			}
   391→			rparen := p.expect(lexer.TokenRparen)
   392→			return &ast.TupleLiteral{
   393→				Elements: elements,
   394→				LParen:   lparen,
   395→				RParen:   rparen,
   396→			}
   397→		}
   398→
   399→		rparen := p.expect(lexer.TokenRparen)
   400→		// 단순 괄호 표현식은 그냥 내부 표현식 반환
   401→		_ = rparen // 위치 정보 사용 가능
   402→		return expr
   403→
   404→	case lexer.TokenLbracket:
   405→		// 배열 리터럴
   406→		return p.parseArrayLiteral()
   407→
   408→	default:
   409→		p.error(fmt.Sprintf("예상치 못한 토큰: %v", p.current.Type))
   410→		return nil
   411→	}
   412→}
