   414→// parseArrayLiteral - 배열 리터럴 파싱 ([1, 2, 3])
   415→func (p *Parser) parseArrayLiteral() ast.Expr {
   416→	lbracket := p.current
   417→	p.advance()
   418→
   419→	elements := [][]ast.Expr{}
   420→	row := []ast.Expr{}
   421→
   422→	for p.current.Type != lexer.TokenRbracket {
   423→		expr := p.parseExpression()
   424→		if expr == nil {
   425→			p.error("배열 요소가 필요합니다")
   426→			return nil
   427→		}
   428→		row = append(row, expr)
   429→
   430→		if p.match(lexer.TokenComma) {
   431→			continue
   432→		} else if p.match(lexer.TokenSemicolon) {
   433→			elements = append(elements, row)
   434→			row = []ast.Expr{}
   435→		} else {
   436→			break
   437→		}
   438→	}
   439→
   440→	if len(row) > 0 {
   441→		elements = append(elements, row)
   442→	}
   443→
   444→	rbracket := p.expect(lexer.TokenRbracket)
   445→	return &ast.ArrayLiteral{
   446→		Elements: elements,
   447→		LBracket: lbracket,
   448→		RBracket: rbracket,
   449→	}
   450→}
