   475→// parseFunctionDecl - 함수 선언 파싱
   476→func (p *Parser) parseFunctionDecl() ast.Stmt {
   477→	funcToken := p.current
   478→	p.advance()
   479→
   480→	if p.current.Type != lexer.TokenIdentifier {
   481→		p.error("함수 이름이 필요합니다")
   482→		return nil
   483→	}
   484→	name := p.current.Lexeme
   485→	p.advance()
   486→
   487→	// 매개변수 파싱
   488→	p.expect(lexer.TokenLparen)
   489→	params := []*ast.Parameter{}
   490→	for p.current.Type != lexer.TokenRparen {
   491→		if p.current.Type != lexer.TokenIdentifier {
   492→			p.error("매개변수 이름이 필요합니다")
   493→			return nil
   494→		}
   495→		paramName := p.current.Lexeme
   496→		p.advance()
   497→
   498→		param := &ast.Parameter{Name: paramName}
   499→		// TODO: 타입, 기본값, 가변 인자 처리
   500→		params = append(params, param)
   501→
   502→		if !p.match(lexer.TokenComma) {
   503→			break
   504→		}
   505→	}
   506→	p.expect(lexer.TokenRparen)
   507→
   508→	// 반환 타입 (옵션)
   509→	var returnType string
   510→	if p.match(lexer.TokenDoubleColon) {
   511→		if p.current.Type != lexer.TokenIdentifier {
   512→			p.error("반환 타입이 필요합니다")
   513→			return nil
   514→		}
   515→		returnType = p.current.Lexeme
   516→		p.advance()
   517→	}
   518→
   519→	// 함수 본체 파싱
   520→	body := p.parseBlock(lexer.TokenKeywordEnd)
   521→	p.expect(lexer.TokenKeywordEnd)
   522→
   523→	return &ast.FunctionDecl{
   524→		Name:       name,
   525→		Parameters: params,
   526→		ReturnType: returnType,
   527→		Body:       body,
   528→		Function:   funcToken,
   529→	}
   530→}
