   846→// getPrecedence - 연산자의 우선순위 얻기
   847→func (p *Parser) getPrecedence(tokenType lexer.TokenType) int {
   848→	if prec, ok := p.precMap[tokenType]; ok {
   849→		return prec
   850→	}
   851→	return 0
   852→}
